        "x_i = x_{i-1} + lambda_{i-1}; t_i = t_{i-1} + lambda_{i-1}/q_{i-1}; t_S = infinity (flight)",
        "x_i = x_i + l_i; t_i = t_i + l_i/u_i; t_S = 1/k_i (dive)",
        "L_c = n * lambda_bar = (v_bar/(r_bar*k)) * (xi0^2/(2*d_c))"
      ],
      "variable_names": [
        "lambda",
        "q",
        "l",
        "u",
        "k",
        "t_S",
        "L_c",
        "xi0",
        "d_c",
        "v_bar",
        "r_bar"
      ],
      "parameters": [
        {
          "name": "beta_pore_size_exponent",
          "value": 0.6,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "Exponent in pore size distribution p_xi(xi) ~ xi^{-beta} exp(-xi/xi0)",
          "anchors": [
            {
              "line_start": 87,
              "line_end": 90,
              "support": "p_xi(xi) ~ xi^{-beta} e^{-xi/xi0}, with beta = 0.6, xi0 = 0.063 mm"
            }
          ]
        },
        {
          "name": "xi0_pore_size_cutoff",
          "value": 0.063,
          "uncertainty": "source_unspecified",
          "unit": "mm",
          "role": "Exponential cutoff in pore size distribution",
          "anchors": [
            {
              "line_start": 87,
              "line_end": 90,
              "support": "xi0 = 0.063 mm"
            }
          ]
        },
        {
          "name": "dc_critical_distance_macroscopic",
          "value": 0.01,
          "uncertainty": "source_unspecified",
          "unit": "um",
          "role": "Critical distance for dive definition used in macroscopic model prediction",
          "anchors": [
            {
              "line_start": 217,
              "line_end": 217,
              "support": "we use our model prediction with the designed pore size distribution and d_c = 0.01 um"
            }
          ]
        },
        {
          "name": "k_attachment_rate",
          "value": 0.00043,
          "uncertainty": "source_unspecified",
          "unit": "s^-1",
          "role": "Effective attachment rate in A-CTRW model",
          "anchors": [
            {
              "line_start": 224,
              "line_end": 224,
              "support": "k = 4.3 * 10^{-4} s^{-1}"
