        },
        {
          "name": "v_bar_over_r_bar_k_ratio",
          "value": 1.0,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "Ratio v_bar/(r_bar*k) in L_c formula",
          "anchors": [
            {
              "line_start": 248,
              "line_end": 248,
              "support": "L_c = n * lambda_bar = (v_bar/(r_bar*k)) * (xi0^2/(2*d_c))"
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 148,
          "line_end": 169,
          "support": "Description of A-CTRW model with flights and dives, equations for position and time updates, and attachment rate k."
        },
        {
          "line_start": 245,
          "line_end": 249,
          "support": "Derivation of L_c = n * lambda_bar = (v_bar/(r_bar*k)) * (xi0^2/(2*d_c))."
        }
      ]
    }
  ],
